(()=>{const eligibleForSideRail=window.matchMedia("(min-width: 1200px) and (min-height: 650px)");const slots=[...document.querySelectorAll(".adsense-fallback")];const requested=new WeakSet();const update=()=>{for(const slot of slots){slot.hidden=eligibleForSideRail.matches;if(!slot.hidden&&!requested.has(slot)){requested.add(slot);(window.adsbygoogle=window.adsbygoogle||[]).push({});}}};eligibleForSideRail.addEventListener("change",update);update();})();
